import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Paper,
  Grid,
  Card,
  CardContent,
  Button,
  Box,
  Chip,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Alert,
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Tab,
  Tabs
} from '@mui/material';
import { 
  People as PeopleIcon, 
  Business as BusinessIcon, 
  School as SchoolIcon,
  Work as WorkIcon,
  Assignment as AssignmentIcon,
  Add as AddIcon,
  Check as CheckIcon,
  Close as CloseIcon,
  Warning as WarningIcon
} from '@mui/icons-material';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { adminAPI } from '../services/api';

const AdminDashboard = () => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const [stats, setStats] = useState(null);
  const [pendingCompanies, setPendingCompanies] = useState([]);
  const [recentActivities, setRecentActivities] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [activeTab, setActiveTab] = useState(0);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [dialogType, setDialogType] = useState('');
  const [formData, setFormData] = useState({});

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const response = await adminAPI.getDashboardStats();
      setStats(response.data.stats);
      setPendingCompanies(response.data.pendingCompanies);
      setRecentActivities(response.data.recentActivities || []);
    } catch (err) {
      setError('Failed to load dashboard data');
    } finally {
      setLoading(false);
    }
  };

  const handleCompanyStatusUpdate = async (companyId, status) => {
    try {
      setError('');
      await adminAPI.manageCompanyStatus(companyId, status);
      setSuccess(`Company status updated to ${status}`);
      fetchDashboardData();
    } catch (err) {
      setError('Failed to update company status');
    }
  };

  const handleOpenDialog = (type) => {
    setDialogType(type);
    setDialogOpen(true);
    setFormData({});
  };

  const handleCloseDialog = () => {
    setDialogOpen(false);
    setDialogType('');
    setFormData({});
  };

  const handleFormSubmit = async (e) => {
    e.preventDefault();
    try {
      setError('');
      let response;

      switch (dialogType) {
        case 'institution':
          response = await adminAPI.createInstitution(formData);
          setSuccess('Institution created successfully');
          break;
        case 'faculty':
          response = await adminAPI.createFaculty(formData);
          setSuccess('Faculty created successfully');
          break;
        case 'course':
          response = await adminAPI.createCourse(formData);
          setSuccess('Course created successfully');
          break;
        default:
          throw new Error('Unknown dialog type');
      }

      handleCloseDialog();
      fetchDashboardData();
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to create');
    }
  };

  const StatCard = ({ title, value, icon, color }) => (
    <Card>
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Box>
            <Typography color="textSecondary" gutterBottom variant="overline">
              {title}
            </Typography>
            <Typography variant="h4" component="div">
              {value}
            </Typography>
          </Box>
          <Box sx={{ color: color, fontSize: 40 }}>
            {icon}
          </Box>
        </Box>
      </CardContent>
    </Card>
  );

  if (loading) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4, mb: 4, display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '50vh' }}>
        <CircularProgress />
      </Container>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Admin Dashboard
      </Typography>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError('')}>
          {error}
        </Alert>
      )}

      {success && (
        <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccess('')}>
          {success}
        </Alert>
      )}

      {/* Statistics Cards */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Total Students"
            value={stats?.students || 0}
            icon={<PeopleIcon />}
            color="#1976d2"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Institutions"
            value={stats?.institutions || 0}
            icon={<SchoolIcon />}
            color="#2e7d32"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Companies"
            value={stats?.companies || 0}
            icon={<BusinessIcon />}
            color="#ed6c02"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Applications"
            value={stats?.applications || 0}
            icon={<AssignmentIcon />}
            color="#9c27b0"
          />
        </Grid>
      </Grid>

      <Grid container spacing={3}>
        {/* Quick Actions */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Quick Actions
              </Typography>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                <Button 
                  variant="contained" 
                  onClick={() => navigate('/admin/users')}
                  startIcon={<PeopleIcon />}
                >
                  Manage Users
                </Button>
                <Button 
                  variant="outlined" 
                  onClick={() => navigate('/admin/companies')}
                  startIcon={<BusinessIcon />}
                >
                  Manage Companies ({stats?.pendingCompanies || 0} pending)
                </Button>
                <Button 
                  variant="outlined" 
                  onClick={() => navigate('/admin/institutions')}
                  startIcon={<SchoolIcon />}
                >
                  Manage Institutions
                </Button>
                <Button 
                  variant="outlined" 
                  onClick={() => navigate('/admin/reports')}
                  startIcon={<AssignmentIcon />}
                >
                  View Reports
                </Button>
              </Box>

              <Typography variant="h6" gutterBottom sx={{ mt: 3 }}>
                Create New
              </Typography>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                <Button 
                  variant="outlined" 
                  onClick={() => handleOpenDialog('institution')}
                  startIcon={<AddIcon />}
                >
                  Add Institution
                </Button>
                <Button 
                  variant="outlined" 
                  onClick={() => handleOpenDialog('faculty')}
                  startIcon={<AddIcon />}
                >
                  Add Faculty
                </Button>
                <Button 
                  variant="outlined" 
                  onClick={() => handleOpenDialog('course')}
                  startIcon={<AddIcon />}
                >
                  Add Course
                </Button>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        {/* Pending Companies */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Pending Company Approvals
              </Typography>
              {pendingCompanies.length === 0 ? (
                <Typography variant="body2" color="textSecondary" sx={{ textAlign: 'center', py: 2 }}>
                  No pending companies for approval
                </Typography>
              ) : (
                <TableContainer>
                  <Table size="small">
                    <TableHead>
                      <TableRow>
                        <TableCell>Company</TableCell>
                        <TableCell>Industry</TableCell>
                        <TableCell>Actions</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {pendingCompanies.map((company) => (
                        <TableRow key={company.id}>
                          <TableCell>
                            <Typography variant="body2" fontWeight="bold">
                              {company.name}
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                              {company.email}
                            </Typography>
                          </TableCell>
                          <TableCell>
                            <Chip label={company.industry} size="small" />
                          </TableCell>
                          <TableCell>
                            <Box sx={{ display: 'flex', gap: 1 }}>
                              <Button
                                size="small"
                                color="success"
                                startIcon={<CheckIcon />}
                                onClick={() => handleCompanyStatusUpdate(company.id, 'approved')}
                              >
                                Approve
                              </Button>
                              <Button
                                size="small"
                                color="error"
                                startIcon={<CloseIcon />}
                                onClick={() => handleCompanyStatusUpdate(company.id, 'rejected')}
                              >
                                Reject
                              </Button>
                            </Box>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              )}
            </CardContent>
          </Card>
        </Grid>

        {/* Recent Activities */}
        <Grid item xs={12}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Recent Activities
              </Typography>
              {recentActivities.length === 0 ? (
                <Typography variant="body2" color="textSecondary" sx={{ textAlign: 'center', py: 2 }}>
                  No recent activities
                </Typography>
              ) : (
                <TableContainer>
                  <Table size="small">
                    <TableHead>
                      <TableRow>
                        <TableCell>Activity</TableCell>
                        <TableCell>Status</TableCell>
                        <TableCell>Time</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {recentActivities.map((activity, index) => (
                        <TableRow key={index}>
                          <TableCell>{activity.message}</TableCell>
                          <TableCell>
                            <Chip 
                              label={activity.status} 
                              color={
                                activity.status === 'admitted' ? 'success' :
                                activity.status === 'rejected' ? 'error' : 'default'
                              }
                              size="small"
                            />
                          </TableCell>
                          <TableCell>
                            {new Date(activity.timestamp).toLocaleString()}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              )}
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Create Dialog */}
      <Dialog open={dialogOpen} onClose={handleCloseDialog} maxWidth="sm" fullWidth>
        <DialogTitle>
          {dialogType === 'institution' && 'Add New Institution'}
          {dialogType === 'faculty' && 'Add New Faculty'}
          {dialogType === 'course' && 'Add New Course'}
        </DialogTitle>
        <form onSubmit={handleFormSubmit}>
          <DialogContent>
            {dialogType === 'institution' && (
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                <TextField
                  label="Institution Name"
                  value={formData.name || ''}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  required
                  fullWidth
                />
                <TextField
                  label="Email"
                  type="email"
                  value={formData.email || ''}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  required
                  fullWidth
                />
                <TextField
                  label="Phone"
                  value={formData.phone || ''}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  fullWidth
                />
                <TextField
                  label="Address"
                  multiline
                  rows={2}
                  value={formData.address || ''}
                  onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                  fullWidth
                />
                <TextField
                  label="Description"
                  multiline
                  rows={3}
                  value={formData.description || ''}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  fullWidth
                />
              </Box>
            )}

            {dialogType === 'faculty' && (
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                <TextField
                  label="Faculty Name"
                  value={formData.name || ''}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  required
                  fullWidth
                />
                <TextField
                  label="Institution ID"
                  value={formData.institutionId || ''}
                  onChange={(e) => setFormData({ ...formData, institutionId: e.target.value })}
                  required
                  fullWidth
                  placeholder="Enter institution document ID"
                />
                <TextField
                  label="Description"
                  multiline
                  rows={3}
                  value={formData.description || ''}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  fullWidth
                />
              </Box>
            )}

            {dialogType === 'course' && (
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                <TextField
                  label="Course Name"
                  value={formData.name || ''}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  required
                  fullWidth
                />
                <TextField
                  label="Institution ID"
                  value={formData.institutionId || ''}
                  onChange={(e) => setFormData({ ...formData, institutionId: e.target.value })}
                  required
                  fullWidth
                />
                <TextField
                  label="Faculty ID"
                  value={formData.facultyId || ''}
                  onChange={(e) => setFormData({ ...formData, facultyId: e.target.value })}
                  required
                  fullWidth
                />
                <TextField
                  label="Description"
                  multiline
                  rows={2}
                  value={formData.description || ''}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  required
                  fullWidth
                />
                <TextField
                  label="Duration"
                  value={formData.duration || ''}
                  onChange={(e) => setFormData({ ...formData, duration: e.target.value })}
                  required
                  fullWidth
                  placeholder="e.g., 4 years"
                />
                <TextField
                  label="Fees"
                  type="number"
                  value={formData.fees || ''}
                  onChange={(e) => setFormData({ ...formData, fees: e.target.value })}
                  required
                  fullWidth
                />
                <TextField
                  label="Seats"
                  type="number"
                  value={formData.seats || ''}
                  onChange={(e) => setFormData({ ...formData, seats: e.target.value })}
                  required
                  fullWidth
                />
              </Box>
            )}
          </DialogContent>
          <DialogActions>
            <Button onClick={handleCloseDialog}>Cancel</Button>
            <Button type="submit" variant="contained">
              Create
            </Button>
          </DialogActions>
        </form>
      </Dialog>
    </Container>
  );
};

export default AdminDashboard;
